from collections import deque

def countSubarraysWithDistantSums(nums: list[int], threshold: int) -> int:
    n = len(nums)
    total = n * (n + 1) // 2
    if threshold <= 0:
        return total

    # Count subarrays with max - min < threshold
    max_dq = deque()
    min_dq = deque()
    left = 0
    narrow = 0

    for right in range(n):
        while max_dq and nums[max_dq[-1]] <= nums[right]:
            max_dq.pop()
        max_dq.append(right)

        while min_dq and nums[min_dq[-1]] >= nums[right]:
            min_dq.pop()
        min_dq.append(right)

        while nums[max_dq[0]] - nums[min_dq[0]] >= threshold:
            left += 1
            if max_dq[0] < left:
                max_dq.popleft()
            if min_dq[0] < left:
                min_dq.popleft()

        narrow += right - left + 1

    return total - narrow

#include <vector>
#include <deque>

class Solution {
public:
    long long countSubarraysWithDistantSums(std::vector<int>& nums, int threshold) {
        long long n = nums.size();
        long long total = n * (n + 1) / 2;
        if (threshold <= 0) return total;

        std::deque<int> max_dq, min_dq;
        int left = 0;
        long long narrow = 0;

        for (int right = 0; right < n; ++right) {
            while (!max_dq.empty() && nums[max_dq.back()] <= nums[right]) {
                max_dq.pop_back();
            }
            max_dq.push_back(right);

            while (!min_dq.empty() && nums[min_dq.back()] >= nums[right]) {
                min_dq.pop_back();
            }
            min_dq.push_back(right);

            while (nums[max_dq.front()] - nums[min_dq.front()] >= threshold) {
                left++;
                if (max_dq.front() < left) max_dq.pop_front();
                if (min_dq.front() < left) min_dq.pop_front();
            }

            narrow += right - left + 1;
        }
        return total - narrow;
    }
};

import java.util.*;

class Solution {
    public long countSubarraysWithDistantSums(int[] nums, int threshold) {
        long n = nums.length;
        long total = n * (n + 1) / 2;
        if (threshold <= 0) return total;

        ArrayDeque<Integer> maxDq = new ArrayDeque<>();
        ArrayDeque<Integer> minDq = new ArrayDeque<>();
        int left = 0;
        long narrow = 0;

        for (int right = 0; right < n; right++) {
            while (!maxDq.isEmpty() && nums[maxDq.peekLast()] <= nums[right]) {
                maxDq.pollLast();
            }
            maxDq.offerLast(right);

            while (!minDq.isEmpty() && nums[minDq.peekLast()] >= nums[right]) {
                minDq.pollLast();
            }
            minDq.offerLast(right);

            while (nums[maxDq.peekFirst()] - nums[minDq.peekFirst()] >= threshold) {
                left++;
                if (maxDq.peekFirst() < left) maxDq.pollFirst();
                if (minDq.peekFirst() < left) minDq.pollFirst();
            }

            narrow += right - left + 1;
        }
        return total - narrow;
    }
}

